<?php

declare(strict_types=1);
const ADMINISTRATOR_SETTING_KEYS = ['system_name', 'email_configuration', 'registration_enabled'];
function get_administrator_settings(): never { $admin=require_administrator();$c=database_connection();$s=$c->prepare("SELECT preference_key,preference_value FROM user_preferences WHERE user_id=? AND preference_key IN ('system_name','email_configuration','registration_enabled')");$s->bind_param('i',$admin['user_id']);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$settings=['system_name'=>'Maseno Pathfinder Graduate Tracer System','email_configuration'=>'','registration_enabled'=>'true'];foreach($rows as $row)$settings[$row['preference_key']]=$row['preference_value'];json_success('System settings retrieved successfully.',$settings); }
function update_administrator_settings(): never { $admin=require_administrator();$input=request_json_body();$c=database_connection();$c->begin_transaction();try{foreach(ADMINISTRATOR_SETTING_KEYS as $key){if(!array_key_exists($key,$input))continue;$value=$input[$key];if(is_bool($value))$value=$value?'true':'false';if(!is_string($value)||mb_strlen(trim($value))>255)json_error('Validation failed.',[$key=>'This setting is invalid.'],422);$value=trim($value);$s=$c->prepare('INSERT INTO user_preferences (user_id,preference_key,preference_value) VALUES (?,?,?) ON DUPLICATE KEY UPDATE preference_value=VALUES(preference_value)');$s->bind_param('iss',$admin['user_id'],$key,$value);$s->execute();$s->close();}$c->commit();}catch(Throwable $e){$c->rollback();throw $e;}get_administrator_settings(); }
